cd /workspace/submission && cat controller.py && python3 - << 'EOF'
import ast, sys
for fn in ('controller.py','planlib.py','graphlib.py','valid.py','main.py'):
    src=open(fn).read(); tree=ast.parse(src)
    imported=set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names: imported.add((a.asname or a.name).split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            for a in node.names: imported.add(a.asname or a.name)
    used={n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    # attribute bases
    bases={n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    unused=[i for i in imported if i not in used and i not in bases]
    print(fn, 'unused imports:', unused)
EOF
